// And groups predicates with the AND operator between them.
func And(predicates ...predicate.UnitAccount) predicate.UnitAccount {
	return predicate.UnitAccount(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UnitAccount) predicate.UnitAccount {
	return predicate.UnitAccount(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UnitAccount) predicate.UnitAccount {
	return predicate.UnitAccount(sql.NotPredicates(p))
}
